CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(120) NOT NULL,email VARCHAR(255) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER',status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),CONSTRAINT chk_user_role CHECK(role IN ('CUSTOMER','SELLER','ADMIN')),CONSTRAINT chk_user_status CHECK(status IN ('ACTIVE','INACTIVE','BLOCKED')));
CREATE TABLE seller_profiles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL UNIQUE,business_name VARCHAR(180) NOT NULL,gst_number VARCHAR(30) UNIQUE,status VARCHAR(20) NOT NULL DEFAULT 'PENDING',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT chk_seller_status CHECK(status IN ('PENDING','APPROVED','SUSPENDED')));
CREATE TABLE categories(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name VARCHAR(120) NOT NULL UNIQUE,parent_id UUID REFERENCES categories(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE products(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),seller_id UUID NOT NULL,category_id UUID NOT NULL,name VARCHAR(200) NOT NULL,description TEXT,price NUMERIC(12,2) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'DRAFT',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(seller_id) REFERENCES seller_profiles(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,CONSTRAINT chk_price CHECK(price>=0),CONSTRAINT chk_product_status CHECK(status IN ('DRAFT','ACTIVE','INACTIVE','ARCHIVED')));
CREATE INDEX idx_products_category_status ON products(category_id,status); CREATE INDEX idx_products_seller ON products(seller_id); CREATE INDEX idx_products_created ON products(created_at DESC);
CREATE TABLE inventory(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),product_id UUID NOT NULL UNIQUE,available_quantity INT NOT NULL DEFAULT 0,reserved_quantity INT NOT NULL DEFAULT 0,version BIGINT NOT NULL DEFAULT 0,updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,CONSTRAINT chk_available CHECK(available_quantity>=0),CONSTRAINT chk_reserved CHECK(reserved_quantity>=0));
CREATE TABLE carts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),cart_id UUID NOT NULL,product_id UUID NOT NULL,quantity INT NOT NULL,UNIQUE(cart_id,product_id),FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,CONSTRAINT chk_cart_qty CHECK(quantity>0));
CREATE TABLE orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,total_amount NUMERIC(12,2) NOT NULL,status VARCHAR(30) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_order_total CHECK(total_amount>=0));
CREATE INDEX idx_orders_user_created ON orders(user_id,created_at DESC); CREATE INDEX idx_orders_status ON orders(status);
CREATE TABLE order_items(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL,product_id UUID NOT NULL,seller_id UUID NOT NULL,quantity INT NOT NULL,price NUMERIC(12,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE RESTRICT,FOREIGN KEY(seller_id) REFERENCES seller_profiles(id) ON DELETE RESTRICT,CONSTRAINT chk_order_qty CHECK(quantity>0),CONSTRAINT chk_order_price CHECK(price>=0));
CREATE TABLE payments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),order_id UUID NOT NULL UNIQUE,amount NUMERIC(12,2) NOT NULL,status VARCHAR(20) NOT NULL,transaction_id VARCHAR(120) UNIQUE,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE RESTRICT);
CREATE TABLE reviews(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),product_id UUID NOT NULL,user_id UUID NOT NULL,rating SMALLINT NOT NULL,comment TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(product_id,user_id),FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT chk_rating CHECK(rating BETWEEN 1 AND 5));
CREATE TABLE wishlists(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL,product_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(user_id,product_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
